        id: PROVIDER_ID,
        name: "Claude Code",
        // Availability follows the local CLI login, not an OpenCode credential:
        // the integration below is only the sign-in button.
        activation: "enabled",
        package: OPENAI_COMPATIBLE_PACKAGE,
        settings: {
            baseURL,
            provider: PROVIDER_ID,
            apiKey: "claude-code-proxy",
